// SYNTHETIC learning fixture (not production code).
const table = { add: (a, b) => a + b, sub: (a, b) => a - b };

function compute(kind, a, b) {
  const fn = table[kind];
  if (!fn) throw new Error("unknown op");
  return fn(a, b);
}

module.exports = { compute };
